__author__ = "Pavlos Desopoulos"
__copyright__ = "Pavlos Desopoulos"

APP_TITLE = "PZTH Full Code Launcher"
AUTHOR_NAME = "Pavlos Desopoulos"
EXPORT_DIR_NAME = "PZTH_full_code_launcher_exports"
RUN_DIR_NAME = "PZTH_full_code_launcher_runs"


def load_payload():
    raw = zlib.decompress(base64.b64decode(DATA_B64.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def safe_name(text, suffix=".py"):
    name = re.sub(r"[^A-Za-z0-9]+", "_", text).strip("_").lower()[:70]
    if not name:
        name = "book_code"
    if suffix and not name.endswith(suffix):
        name += suffix
    return name


class LauncherApp(tk.Tk):
    def __init__(self):
        super().__init__()
        self.payload = load_payload()
        self.items = self.payload["items"]
        self.process = None
        self.reader_threads = []
        self.run_dir = Path.cwd() / RUN_DIR_NAME
        self.run_dir.mkdir(exist_ok=True)
        self.export_dir = Path.cwd() / EXPORT_DIR_NAME
        self.export_dir.mkdir(exist_ok=True)

        self.title(APP_TITLE)
        self.geometry("1320x820")
        self.minsize(1100, 680)
        self.configure(bg="#1f2329")

        self.chapter_var = tk.StringVar()
        self.type_var = tk.StringVar()
        self.search_var = tk.StringVar()
        self.status_var = tk.StringVar(value="Ready.")
        self.input_var = tk.StringVar()

        self._build_style()
        self._build_layout()
        self._load_menus()
        self._select_defaults()
        self.protocol("WM_DELETE_WINDOW", self.on_close)

    def _build_style(self):
        self.style = ttk.Style(self)
        try:
            self.style.theme_use("clam")
        except tk.TclError:
            pass
        self.style.configure("TFrame", background="#1f2329")
        self.style.configure("Panel.TFrame", background="#2b3038")
        self.style.configure("TLabel", background="#1f2329", foreground="#e8edf2", font=("Segoe UI", 10))
        self.style.configure("Muted.TLabel", background="#1f2329", foreground="#9ca8b3", font=("Segoe UI", 9))
        self.style.configure("Title.TLabel", background="#1f2329", foreground="#ffffff", font=("Segoe UI", 18, "bold"))
        self.style.configure("Header.TLabel", background="#2b3038", foreground="#ffffff", font=("Segoe UI", 11, "bold"))
        self.style.configure("TButton", font=("Segoe UI", 10), padding=(10, 6))
        self.style.configure("Accent.TButton", font=("Segoe UI", 10, "bold"), padding=(12, 7))
        self.style.configure("TCombobox", fieldbackground="#ffffff", background="#ffffff")
        self.style.configure("Treeview", font=("Segoe UI", 9), rowheight=25, background="#f7f7f7", fieldbackground="#f7f7f7")
        self.style.configure("Treeview.Heading", font=("Segoe UI", 9, "bold"))

    def _build_layout(self):
        top = ttk.Frame(self)
        top.pack(fill="x", padx=18, pady=(14, 8))
        ttk.Label(top, text=APP_TITLE, style="Title.TLabel").pack(side="left")
        ttk.Label(top, text=f"by {AUTHOR_NAME}", style="Muted.TLabel").pack(side="right", pady=(7, 0))

        main = ttk.Frame(self)
        main.pack(fill="both", expand=True, padx=18, pady=(0, 12))
        main.columnconfigure(0, weight=0)
        main.columnconfigure(1, weight=1)
        main.rowconfigure(0, weight=1)

        left = ttk.Frame(main, style="Panel.TFrame")
        left.grid(row=0, column=0, sticky="nsw", padx=(0, 12))
        left.configure(width=360)
        left.grid_propagate(False)

        filter_box = ttk.Frame(left, style="Panel.TFrame")
        filter_box.pack(fill="x", padx=12, pady=12)
        ttk.Label(filter_box, text="Choose code", style="Header.TLabel").pack(anchor="w", pady=(0, 8))

        ttk.Label(filter_box, text="Chapter", style="Header.TLabel").pack(anchor="w")
        self.chapter_combo = ttk.Combobox(filter_box, textvariable=self.chapter_var, state="readonly", width=42)
        self.chapter_combo.pack(fill="x", pady=(2, 8))
        self.chapter_combo.bind("<<ComboboxSelected>>", lambda e: self._refresh_types())

        ttk.Label(filter_box, text="Type", style="Header.TLabel").pack(anchor="w")
        self.type_combo = ttk.Combobox(filter_box, textvariable=self.type_var, state="readonly", width=42)
        self.type_combo.pack(fill="x", pady=(2, 8))
        self.type_combo.bind("<<ComboboxSelected>>", lambda e: self._refresh_list())

        ttk.Label(filter_box, text="Search title/code", style="Header.TLabel").pack(anchor="w")
        search_entry = ttk.Entry(filter_box, textvariable=self.search_var)
        search_entry.pack(fill="x", pady=(2, 8))
        search_entry.bind("<KeyRelease>", lambda e: self._refresh_list())

        btn_row = ttk.Frame(filter_box, style="Panel.TFrame")
        btn_row.pack(fill="x", pady=(4, 0))
        ttk.Button(btn_row, text="Run", style="Accent.TButton", command=self.run_selected).pack(side="left", padx=(0, 6))
        ttk.Button(btn_row, text="Stop", command=self.stop_process).pack(side="left", padx=(0, 6))
        ttk.Button(btn_row, text="Export", command=self.export_selected).pack(side="left")

        ttk.Button(filter_box, text="Export all code blocks", command=self.export_all).pack(fill="x", pady=(8, 0))

        ttk.Label(left, text="Items", style="Header.TLabel").pack(anchor="w", padx=12, pady=(8, 4))
        self.tree = ttk.Treeview(left, columns=("type",), show="tree", selectmode="browse")
        self.tree.pack(fill="both", expand=True, padx=12, pady=(0, 12))
        self.tree.bind("<<TreeviewSelect>>", lambda e: self.show_selected())

        right = ttk.Frame(main)
        right.grid(row=0, column=1, sticky="nsew")
        right.rowconfigure(1, weight=3)
        right.rowconfigure(3, weight=1)
        right.columnconfigure(0, weight=1)

        self.meta_label = ttk.Label(right, text="", style="Header.TLabel")
        self.meta_label.grid(row=0, column=0, sticky="ew", pady=(0, 6))

        self.code_text = ScrolledText(
            right,
            wrap="none",
            font=("Consolas", 10),
            bg="#0f1216",
            fg="#f4f4f4",
            insertbackground="#ffffff",
            selectbackground="#536d8b",
            relief="flat",
            borderwidth=8,
        )
        self.code_text.grid(row=1, column=0, sticky="nsew")

        runbar = ttk.Frame(right)
        runbar.grid(row=2, column=0, sticky="ew", pady=(8, 6))
        ttk.Label(runbar, text="Input for console programs:").pack(side="left")
        input_entry = ttk.Entry(runbar, textvariable=self.input_var)
        input_entry.pack(side="left", fill="x", expand=True, padx=8)
        input_entry.bind("<Return>", lambda e: self.send_input())
        ttk.Button(runbar, text="Send input", command=self.send_input).pack(side="left", padx=(0, 6))
        ttk.Button(runbar, text="Clear output", command=lambda: self.output_text.delete("1.0", "end")).pack(side="left")

        self.output_text = ScrolledText(
            right,
            wrap="word",
            font=("Consolas", 10),
            bg="#151a20",
            fg="#e6edf3",
            insertbackground="#ffffff",
            selectbackground="#536d8b",
            relief="flat",
            borderwidth=8,
            height=10,
        )
        self.output_text.grid(row=3, column=0, sticky="nsew")

        status = ttk.Label(self, textvariable=self.status_var, style="Muted.TLabel")
        status.pack(fill="x", padx=18, pady=(0, 10))

    def _load_menus(self):
        self.section_key_by_label = {
            section["label"]: section["key"] for section in self.payload.get("sections", [])
        }
        labels = [section["label"] for section in self.payload.get("sections", [])]
        self.chapter_combo["values"] = labels

    def _select_defaults(self):
        vals = list(self.chapter_combo["values"])
        default_section = next((v for v in vals if v.startswith("Chapter 1:")), vals[0] if vals else "")
        self.chapter_var.set(default_section)
        self._refresh_types(default_type="Project")

    def _current_section_key(self):
        return self.section_key_by_label.get(self.chapter_var.get())

    def _refresh_types(self, default_type=None):
        section_key = self._current_section_key()
        types = []
        for item in self.items:
            if item["section_key"] == section_key and item["type"] not in types:
                types.append(item["type"])
        preferred = ["Project", "Worked Example", "Example", "Solved Exercise", "Twin / Hint", "Wrong / Right", "Debug / Fix Drill", "Extension", "Terminal", "File Tree"]
        types = sorted(types, key=lambda t: preferred.index(t) if t in preferred else 99)
        self.type_combo["values"] = types
        if default_type in types:
            self.type_var.set(default_type)
        elif types:
            self.type_var.set(types[0])
        else:
            self.type_var.set("")
        self._refresh_list()

    def _matching_items(self):
        section_key = self._current_section_key()
        typ = self.type_var.get()
        q = self.search_var.get().strip().lower()
        found = []
        for item in self.items:
            if item["section_key"] != section_key or item["type"] != typ:
                continue
            hay = (item["title"] + "\n" + item["display_code"]).lower()
            if q and q not in hay:
                continue
            found.append(item)
        return found

    def _refresh_list(self):
        self.tree.delete(*self.tree.get_children())
        for item in self._matching_items():
            label = item["title"]
            if item.get("files"):
                label += "  [multi-file]"
            self.tree.insert("", "end", iid=item["id"], text=label)
        children = self.tree.get_children()
        if children:
            self.tree.selection_set(children[0])
            self.tree.focus(children[0])
            self.show_selected()
        else:
            self.code_text.delete("1.0", "end")
            self.meta_label.config(text="No items found.")

    def selected_item(self):
        sel = self.tree.selection()
        if not sel:
            return None
        iid = sel[0]
        return next((item for item in self.items if item["id"] == iid), None)

    def show_selected(self):
        item = self.selected_item()
        if not item:
            return
        self.code_text.delete("1.0", "end")
        self.code_text.insert("1.0", item["display_code"])
        lines = item["display_code"].count("\n") + 1
        extra = "multi-file · " if item.get("files") else ""
        self.meta_label.config(
            text=f"{item['section_label']} · {item['type']} · {extra}{item['title']} · {lines} lines"
        )
        self.status_var.set(item.get("notes") or "Ready.")

    def _write_item_files(self, item):
        stamp = time.strftime("%Y%m%d_%H%M%S")
        folder = self.run_dir / f"{item['id']}_{stamp}"
        folder.mkdir(parents=True, exist_ok=True)
        if item.get("files"):
            for fname, code in item["files"].items():
                path = folder / fname
                path.write_text(code, encoding="utf-8")
            main = folder / (item.get("main_file") or "main.py")
            return folder, main
        filename = item.get("filename") or safe_name(item["title"])
        if not filename.endswith(".py"):
            filename = safe_name(filename, ".py")
        path = folder / filename
        path.write_text(item["runnable_code"], encoding="utf-8")
        return folder, path

    def run_selected(self):
        item = self.selected_item()
        if not item:
            return
        if not item.get("runnable", True):
            messagebox.showinfo(
                "Reference-only block",
                "This printed block is intentionally incomplete, invalid, terminal text, or a file tree. "
                "It is included for an exact book match but is not run as a standalone Python program.",
            )
            return
        if self.process and self.process.poll() is None:
            messagebox.showwarning("Process already running", "Stop the current run before starting another one.")
            return
        folder, script = self._write_item_files(item)
        self.output_text.insert("end", f"\n[Launcher] Running: {script}\n")
        self.output_text.see("end")
        try:
            self.process = subprocess.Popen(
                [sys.executable, "-u", str(script)],
                cwd=str(folder),
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
        except Exception as exc:
            self.output_text.insert("end", f"[Launcher] Could not start process: {exc}\n")
            self.process = None
            return
        self.status_var.set(f"Running {item['title']}...")
        t = threading.Thread(target=self._read_process_output, daemon=True)
        t.start()
        self.reader_threads.append(t)

    def _read_process_output(self):
        proc = self.process
        if not proc or not proc.stdout:
            return
        try:
            for line in proc.stdout:
                self.output_text.after(0, self._append_output, line)
        except Exception as exc:
            self.output_text.after(0, self._append_output, f"[Launcher reader error] {exc}\n")
        finally:
            code = proc.wait() if proc else 0
            self.output_text.after(0, self._append_output, f"\n[Launcher] Process ended with code {code}.\n")
            self.output_text.after(0, self.status_var.set, "Ready.")

    def _append_output(self, text):
        self.output_text.insert("end", text)
        self.output_text.see("end")

    def send_input(self):
        text = self.input_var.get()
        if not self.process or self.process.poll() is not None or not self.process.stdin:
            self.output_text.insert("end", "[Launcher] No running console process is waiting for input.\n")
            self.output_text.see("end")
            return
        try:
            self.process.stdin.write(text + "\n")
            self.process.stdin.flush()
            self.output_text.insert("end", text + "\n")
            self.output_text.see("end")
            self.input_var.set("")
        except Exception as exc:
            self.output_text.insert("end", f"[Launcher] Could not send input: {exc}\n")

    def stop_process(self):
        if self.process and self.process.poll() is None:
            self.output_text.insert("end", "\n[Launcher] Stopping process...\n")
            try:
                self.process.terminate()
                try:
                    self.process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    self.process.kill()
            except Exception as exc:
                self.output_text.insert("end", f"[Launcher] Stop failed: {exc}\n")
            self.status_var.set("Stopped.")
        else:
            self.status_var.set("No running process.")

    def export_selected(self):
        item = self.selected_item()
        if not item:
            return
        base = filedialog.askdirectory(title="Choose export folder", initialdir=str(self.export_dir))
        if not base:
            return
        base = Path(base)
        self._export_item(item, base)
        messagebox.showinfo("Export complete", f"Exported: {item['title']}\n\nFolder:\n{base}")

    def _export_item(self, item, base):
        section_dir = base / item["section_key"] / safe_name(item["type"], suffix="")
        section_dir.mkdir(parents=True, exist_ok=True)
        if item.get("files"):
            project_dir = section_dir / safe_name(item["title"], suffix="")
            project_dir.mkdir(exist_ok=True)
            for fname, code in item["files"].items():
                (project_dir / fname).write_text(code, encoding="utf-8")
            return project_dir
        path = section_dir / item.get("filename", safe_name(item["title"]))
        content = item["runnable_code"] if item.get("runnable", True) else item["display_code"]
        path.write_text(content, encoding="utf-8")
        return path

    def export_all(self):
        base = filedialog.askdirectory(title="Choose export folder", initialdir=str(self.export_dir))
        if not base:
            return
        base = Path(base)
        count = 0
        for item in self.items:
            self._export_item(item, base)
            count += 1
        manifest = base / "PZTH_FULL_CODE_LAUNCHER_EXPORT_MANIFEST.txt"
        manifest.write_text(
            f"{APP_TITLE} Export\n"
            f"Author: {AUTHOR_NAME}\n"
            f"Items exported: {count}\n"
            "\nRun .py files with Python 3. Tkinter GUI files open their own windows.\n",
            encoding="utf-8",
        )
        messagebox.showinfo("Export all complete", f"Exported {count} items.\n\nFolder:\n{base}")

    def on_close(self):
        self.stop_process()
        self.destroy()


def audit_payload():
    payload = load_payload()
    errors = []
    project_count = 0
    runnable_count = 0
    for item in payload.get("items", []):
        if item.get("type") == "Project":
            project_count += 1
        if not item.get("runnable"):
            continue
        runnable_count += 1
        if item.get("files"):
            for filename, code in item["files"].items():
                try:
                    compile(code, filename, "exec")
                except SyntaxError as exc:
                    errors.append(f"{item['title']} / {filename}: {exc}")
        else:
            try:
                compile(item.get("runnable_code", ""), item.get("filename", "book_code.py"), "exec")
            except SyntaxError as exc:
                errors.append(f"{item['title']}: {exc}")
    print(f"Title: {payload.get('title', APP_TITLE)}")
    print(f"Author: {payload.get('author', AUTHOR_NAME)}")
    print(f"Items: {len(payload.get('items', []))}")
    print(f"Projects: {project_count}")
    print(f"Runnable items checked: {runnable_count}")
    if errors:
        print("AUDIT FAILED")
        for error in errors:
            print(" -", error)
        return 1
    print("AUDIT PASSED")
    return 0


def main():
    if "--audit" in sys.argv:
        raise SystemExit(audit_payload())
    app = LauncherApp()
    app.mainloop()


if __name__ == "__main__":
    main()
